## Building Tic-Tac-Toe

### The Board

```xiom
type Board {
  cells: Vec[Char];
  current_player: Char;
}

fn create_board() -> Board {
  let mut cells: Vec[Char] = Vec[Char].new();
  let mut i = 0;
  while i < 9 { cells.push(' '); i += 1; };
  Board{ cells: cells, current_player: 'X' }
}
```

### Making a Move

```xiom
fn make_move(board: &mut Board, position: Int) -> Bool {
  if position < 0 || position >= 9 { return false; };
  if board.cells.get(position).unwrap() != ' ' {
    return false;
  };
  board.cells.set(position, board.current_player);
  board.current_player = if board.current_player == 'X' { 'O' } else { 'X' };
  true
}
```

### Checking for a Winner

```xiom
fn check_winner(board: &Board) -> Option[Char] {
  let wins: Vec[Vec[Int]] = Vec[Vec[Int]].new();
  wins.push(make_line(0, 1, 2)); wins.push(make_line(3, 4, 5));
  wins.push(make_line(6, 7, 8));
  wins.push(make_line(0, 3, 6)); wins.push(make_line(1, 4, 7));
  wins.push(make_line(2, 5, 8));
  wins.push(make_line(0, 4, 8)); wins.push(make_line(2, 4, 6));

  let mut i = 0;
  while i < wins.len() {
    let line = wins.get(i).unwrap();
    let c0 = board.cells.get(line.get(0).unwrap()).unwrap();
    let c1 = board.cells.get(line.get(1).unwrap()).unwrap();
    let c2 = board.cells.get(line.get(2).unwrap()).unwrap();
    if c0 != ' ' && c0 == c1 && c1 == c2 {
      return Option.Some(c0);
    };
    i += 1;
  };
  Option.None
}
```

### The 8 Winning Lines

```
Rows: [0][1][2], [3][4][5], [6][7][8]
Columns: [0][3][6], [1][4][7], [2][5][8]
Diagonals: [0][4][8], [2][4][6]
```

