use xiom.io;
type TicTacToe = {
  board: Vec[Char];
}

fn check_line(game: &TicTacToe, a: Int, b: Int, c: Int) -> Option[Char] {
  let ca = game.board.get(a).unwrap();
  let cb = game.board.get(b).unwrap();
  let cc = game.board.get(c).unwrap();
  if ca != ' ' && ca == cb && cb == cc { return Some(ca); };
  None
}

fn check_winner(game: &TicTacToe) -> Option[Char] {
  let result = check_line(game, 0, 1, 2); if result.is_some() { return result; };
  let result = check_line(game, 3, 4, 5); if result.is_some() { return result; };
  let result = check_line(game, 6, 7, 8); if result.is_some() { return result; };
  let result = check_line(game, 0, 3, 6); if result.is_some() { return result; };
  let result = check_line(game, 1, 4, 7); if result.is_some() { return result; };
  let result = check_line(game, 2, 5, 8); if result.is_some() { return result; };
  let result = check_line(game, 0, 4, 8); if result.is_some() { return result; };
  let result = check_line(game, 2, 4, 6); if result.is_some() { return result; };
  None
}

fn is_board_full(game: &TicTacToe) -> Bool {
  var i = 0;
  while i < 9 {
    if game.board.get(i).unwrap() == ' ' { return false; };
    i += 1;
  };
  true
}

fn main() -> Int {
  var game = TicTacToe{ board: Vec[Char].new() };
  var i = 0;
  while i < 9 { game.board.push(' '); i += 1; };
  game.board.set(0, 'X'); game.board.set(4, 'O');
  game.board.set(1, 'X'); game.board.set(5, 'O');
  game.board.set(2, 'X');
  let winner = check_winner(&game);
  io.println(winner.is_some().to_str());
  return 0;
}
